#!/usr/bin/env python3
"""Build the Chinese, chapter-based offline handoff guide without dependencies."""
from pathlib import Path
import ast,html,json,os,re
from urllib.parse import urlsplit,unquote
ROOT=Path(__file__).resolve().parents[2]
DOC=ROOT/'01_交接说明'
CHAPTERS=[('01_项目现状.md','overview','项目现状','现在接手什么'),('02_模拟器原理.md','simulator','模拟器原理','退化图怎样生成'),('03_当前方法与代码.md','method','当前方法与代码','已有方法怎样工作'),('04_服务器环境与运行.md','run','服务器环境与运行','怎样接着跑'),('05_论文与素材.md','papers','论文与素材','接下来读什么'),('06_接收与后续安排.md','handover','接收与后续安排','还需要对接什么')]
IDS={name:key for name,key,_,_ in CHAPTERS}
# Reuse only the two pure text-rendering functions; never execute the archived builder.
source=(ROOT/'03_归档资料/tools/receiver/build_reader.py').read_text()
parsed=ast.parse(source); funcs=[n for n in parsed.body if isinstance(n,ast.FunctionDef) and n.name in ('inline','render')]
ns={'html':html,'re':re,'ids':{}}
exec(compile(ast.Module(body=funcs,type_ignores=[]),'<preserved-markdown-renderer>','exec'),ns)
def links(text):
 def replace(m):
  u=urlsplit(m[1])
  if u.scheme or u.netloc or not u.path:return m[0]
  if unquote(u.path) in IDS: return '](#'+IDS[unquote(u.path)]+')'
  dest=(DOC/unquote(u.path)).resolve()
  value=os.path.relpath(dest,ROOT)+('#'+u.fragment if u.fragment else '')
  return ']('+value+')'
 return re.sub(r'\]\(([^)]+)\)',replace,text)
css='''
:root{--ink:#172f39;--muted:#60717a;--accent:#126f6a;--line:#dce5e5;--paper:#fff;--soft:#f3f7f6}*{box-sizing:border-box}body{margin:0;background:#f5f7f6;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;line-height:1.8}a{color:var(--accent);text-underline-offset:3px}header{border-bottom:1px solid var(--line);background:#fff;padding:16px 28px;display:flex;align-items:center;justify-content:space-between;gap:20px}header strong{font-size:19px}header small{font-size:13px;color:var(--muted)}.layout{display:grid;grid-template-columns:235px minmax(0,1080px);max-width:1380px;margin:auto;gap:26px;padding:26px}.sidebar{position:sticky;top:24px;align-self:start}.sidebar p{color:var(--muted);font-size:13px;margin:0 0 14px}.sidebar a{display:flex;gap:12px;align-items:center;padding:13px 14px;margin:4px 0;border-radius:8px;color:var(--ink);text-decoration:none;font-size:14px;line-height:1.5}.sidebar a span{font-size:12px;color:var(--muted)}.sidebar a[aria-current=page]{background:var(--accent);color:#fff}.sidebar a[aria-current=page] span{color:#d0ebe7}.sidebar .archive{margin-top:24px;border-top:1px solid var(--line);padding-top:16px}.archive a{font-size:13px;color:var(--muted)}main{min-width:0}section{background:#fff;border:1px solid var(--line);border-radius:12px;padding:34px 40px;margin-bottom:24px}body.js section{display:none}body.js section.active{display:block}.chapter-label{color:var(--accent);font-size:13px;font-weight:600;margin:0 0 8px}h1{font-size:clamp(25px,3vw,35px);line-height:1.4;margin:0 0 12px}h2{font-size:23px;margin-top:32px;line-height:1.5}h3{font-size:19px;margin-top:28px}.chapter>h2:first-child{display:none}.description{color:var(--muted);margin:0 0 24px}.chapter p{margin:14px 0}.chapter li{margin:7px 0}img{display:block;max-width:100%;height:auto;margin:22px auto}figure{margin:16px 0}figcaption,.caption{font-size:13px;color:var(--muted)}.table-scroll{overflow:auto;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.75}th,td{padding:12px;vertical-align:top;text-align:left;border-bottom:1px solid var(--line)}th{background:var(--soft);font-weight:600}td{min-width:110px}code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;overflow-wrap:anywhere;background:#edf3f2;border-radius:4px;padding:2px 5px}pre{background:#17313c;color:#eff6f6;border-radius:8px;padding:19px;overflow:auto;line-height:1.7;font-size:13px}pre code{background:none;padding:0;overflow-wrap:normal;font-size:inherit}blockquote{border-left:3px solid var(--accent);margin-left:0;padding:4px 18px;background:var(--soft)}.chapter a{overflow-wrap:anywhere}.pager{border-top:1px solid var(--line);margin-top:32px;padding-top:20px;display:flex;justify-content:space-between;gap:16px}.pager a{font-size:14px;text-decoration:none}.demo{background:#f4f8f6;border:1px solid #dce7e0;border-radius:10px;margin:24px 0;padding:22px}.demo h3{margin:0 0 8px}.controls{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:18px 0}.controls input{flex:1;min-width:150px;accent-color:var(--accent)}.controls output{font-weight:700;font-variant-numeric:tabular-nums}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair img{width:100%;max-width:300px;margin:0 auto 10px;border:1px solid #d4ded9}.pair figcaption{text-align:center}.demo button{border:1px solid #aac6bd;color:var(--ink);background:white;border-radius:6px;padding:8px 14px;font:inherit;font-size:14px;cursor:pointer}.demo button[aria-pressed=true]{background:var(--accent);color:white;border-color:var(--accent)}.stage{max-width:280px}.note{font-size:13px;color:var(--muted)}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #d6a449;outline-offset:3px}.footer{font-size:12px;color:var(--muted);padding:0 4px 16px}.file-link{font-size:12px;color:var(--muted)}@media(max-width:850px){header{padding:15px 18px}.layout{display:block;padding:14px}.sidebar{position:static;margin-bottom:18px}.sidebar nav{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.sidebar a{font-size:12px;padding:10px;gap:7px}.sidebar .archive{display:none}.sidebar p{margin-bottom:6px}.chapter>h2{font-size:21px}section{padding:24px 20px}header small{font-size:11px;max-width:135px}h1{font-size:27px}}@media(max-width:480px){.sidebar nav{grid-template-columns:repeat(2,1fr)}.pair{gap:10px}.demo{padding:14px}.controls{gap:8px}th,td{padding:9px;font-size:13px}section{padding:20px 16px}.pager a{font-size:12px}}@media print{body{background:white}header small,.sidebar,.pager,.controls,.file-link{display:none}.layout{display:block;padding:0}section,body.js section{display:block!important;border:0;border-radius:0;padding:0;break-before:page}section:first-child{break-before:auto}pre{white-space:pre-wrap;color:#172f39;background:#f0f4f2}pre code{white-space:pre-wrap}.table-scroll{overflow:visible}img{max-height:520px;object-fit:contain}.demo{break-inside:avoid}}
'''
interactive='''<div class="demo" aria-label="固定随机源的强度演示"><h3>动手看：同一随机源，改变湍流强度</h3><p class="note">切换本次实际渲染的合成图，直观看模糊和扭曲如何变化。这里只切换保存结果，不在浏览器运行模型。</p><div class="controls"><label for="strength">强度 g</label><input id="strength" type="range" min="0" max="5" step="1" value="5" aria-valuetext="g = 4"><output id="strength-value">4</output><span id="time-value">物理时间 t = 0</span></div><div class="pair"><figure><img src="01_交接说明/图解/清晰输入.png" alt="清晰合成输入图"><figcaption>清晰输入</figcaption></figure><figure><img id="strength-image" src="01_交接说明/图解/强度4.png" alt="强度4的完整退化图"><figcaption id="strength-caption">强度 4 的完整退化图</figcaption></figure></div><p id="flow-metric" class="note"></p><h3>再比较：只有模糊，加上扭曲</h3><div class="controls"><button id="blur-button" aria-pressed="true">只有模糊</button><button id="warp-button" aria-pressed="false">模糊＋扭曲</button></div><img id="stage-image" class="stage" src="01_交接说明/图解/强度4_仅模糊.png" alt="强度4仅模糊结果"><p id="stage-caption" class="note">尚未按位移场采样。</p><p class="note">256×256，固定两块原始随机源。显示图裁到[0,1]，计算浮点结果不裁剪。这是模拟器机制示例，不是恢复效果对比。</p></div>'''
parts=['<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>湍流项目交接｜开始阅读</title><link rel="icon" href="data:,"><style>'+css+'</style></head><body><header><strong>湍流项目交接</strong><small>2026年11月4日 · 离线阅读指南</small></header><div class="layout"><aside class="sidebar"><p>按顺序阅读 · 当前方法与运行</p><nav aria-label="交接章节">']
for i,(name,key,title,desc) in enumerate(CHAPTERS,1):parts.append(f'<a href="#{key}" data-chapter="{key}"><span>{i:02d}</span>{title}</a>')
parts.append('<div class="archive"><p>查资料时再打开</p><a href="02_代码与运行/README.md">当前代码说明</a><a href="03_归档资料/归档目录.md">全部历史资料</a></div></nav></aside><main>')
for i,(name,key,title,desc) in enumerate(CHAPTERS):
 body=ns['render'](links((DOC/name).read_text()))
 if key=='simulator':
  idx=body.find('</p>',body.find('<img '))+4
  body=body[:idx]+interactive+body[idx:]
 prev='<a href="#'+CHAPTERS[i-1][1]+'">← '+CHAPTERS[i-1][2]+'</a>' if i else '<span></span>'
 nxt='<a href="#'+CHAPTERS[i+1][1]+'">下一章：'+CHAPTERS[i+1][2]+' →</a>' if i+1<len(CHAPTERS) else '<a href="#overview">返回项目现状 ↑</a>'
 parts.append(f'<section id="{key}" aria-labelledby="title-{key}"><p class="chapter-label">第{i+1}章 / 共6章</p><h1 id="title-{key}">{title}</h1><p class="description">{desc}</p><a class="file-link" href="01_交接说明/{name}">查看本章文字文件</a><article class="chapter">{body}</article><div class="pager">{prev}{nxt}</div></section>')
parts.append('<p class="footer">当前指南、当前代码和历史归档分层保存。资料准备完成不代表新方法已实现；原始证据保持原字节。</p></main></div><script>')
measure=json.loads((ROOT/'03_归档资料/docs/meeting_20261104/evidence/SIMULATOR_CPU.json').read_text())['strengths']
parts.append('const measurements='+json.dumps(measure)+';')
parts.append('''
document.body.classList.add('js');
function showChapter(){let key=location.hash.slice(1)||'overview';if(!document.getElementById(key))key='overview';document.querySelectorAll('main>section').forEach(s=>s.classList.toggle('active',s.id===key));document.querySelectorAll('a[data-chapter]').forEach(a=>{if(a.dataset.chapter===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo(0,0);}
window.addEventListener('hashchange',showChapter);showChapter();
const strengths=[0,0.5,1,2,3,4],slider=document.getElementById('strength');
function updateStrength(){const g=strengths[Number(slider.value)],m=measurements[String(g)];document.getElementById('strength-value').textContent=g;document.getElementById('time-value').textContent='物理时间 t = '+(1-g/4);slider.setAttribute('aria-valuetext','g = '+g);const img=document.getElementById('strength-image');img.src='01_交接说明/图解/强度'+g+'.png';img.alt='强度'+g+'的完整退化图';document.getElementById('strength-caption').textContent='强度 '+g+' 的完整退化图';document.getElementById('flow-metric').textContent='实际像素位移 RMS：'+m.flow_rms_pixels.toFixed(4)+' px · 原始浮点范围：['+m.min.toFixed(4)+', '+m.max.toFixed(4)+']';}
slider.addEventListener('input',updateStrength);updateStrength();
function stage(warp){document.getElementById('stage-image').src='01_交接说明/图解/'+(warp?'强度4':'强度4_仅模糊')+'.png';document.getElementById('stage-image').alt=warp?'强度4的完整退化图':'强度4仅模糊结果';document.getElementById('stage-caption').textContent=warp?'已在模糊图上按位移场采样。':'尚未按位移场采样。';document.getElementById('blur-button').setAttribute('aria-pressed',String(!warp));document.getElementById('warp-button').setAttribute('aria-pressed',String(warp));}
document.getElementById('blur-button').addEventListener('click',()=>stage(false));document.getElementById('warp-button').addEventListener('click',()=>stage(true));
</script></body></html>''')
(ROOT/'开始阅读.html').write_text('\n'.join(parts))
print('已生成：开始阅读.html（六章中文导航，默认只显示当前章）')
